{
  "type": "object",
  "required": ["title", "concepts"],
  "additionalProperties": false,
  "properties": {
    "title": {
      "type": "string",
      "description": "The name of the topic"
    },
    "concepts": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id", "name", "prerequisites", "related"],
        "additionalProperties": false,
        "properties": {
          "id": {
            "type": "string",
            "description": "Short kebab-case identifier"
          },
          "name": {
            "type": "string",
            "description": "Human-readable concept name"
          },
          "prerequisites": {
            "type": "array",
            "items": { "type": "string" },
            "description": "Ids of concepts that must come first"
          },
          "related": {
            "type": "array",
            "items": { "type": "string" },
            "description": "Ids of related concepts"
          }
        }
      }
    }
  }
}
